    s3Body: "UVT — платформаның сыйақы токені. Оның бағасы мен өтімділігі күрт өзгеруі мүмкін, кейде оны саудалау мүмкін болмауы мүмкін. UVT-нің қалай алынатыны, босатылатыны және қолданылатыны платформа жариялаған ережелерге сай.",
