    s4Body: "Құрылғылар сатып алынғаннан кейін әдетте қайтарылмайды, бірақ жаңарту бетіндегі ережелер бойынша Trade-in арқылы ауыстыруға болады. Акция сыйақылары мен сынақ бонустары әр акцияның ережелеріне сай; қайтару жасалса, тиісті сыйақылар кері алынуы мүмкін. Тапсырыс бермес бұрын бағаны, комиссияларды және сатудан кейінгі қызмет ақпаратын тексеріңіз.",
    s5Title: "Толтыру және ақша шығару",
    s5Body: "Толтыру немесе шығару алдында желі мен мекенжайды тексеріңіз; қате желіге не мекенжайға жіберілген активтерді қайтару мүмкін болмауы мүмкін. Блокчейндегі аударым расталғаннан кейін кері қайтарылмайды. Желі комиссиясы мен түсу уақыты желі жағдайына байланысты және бетте көрсетіледі. Ақша шығару қауіпсіздік тексерісін қажет етуі мүмкін, өңдеу уақыты тапсырыс күйінен көрінеді.",
    s6Title: "Шақыру және команда сыйақылары",
    s6Body: "Шақыру және команда сыйақылары шақырылған пайдаланушылардың жарамды әрекетіне және сол кездегі ережелерге байланысты. Ережелер өзгеруі мүмкін, сыйақылардың жалғасатынына кепілдік жоқ. Жалған аккаунттар, жаппай тіркелу немесе спам арқылы алынған сыйақылар жарамсыз деп танылады және аккаунттың тоқтатылуына әкелуі мүмкін.",
    s7Title: "Аккаунт қауіпсіздігі және қызметтің өзгеруі",
    s7Body: "Құпиясөзді, растау кодтарын және төлем PIN-кодын қауіпсіз сақтаңыз; платформа қызметкерлері оларды ешқашан сұрамайды. Аккаунттар мен қаражатты қорғау немесе қолданыстағы заңды сақтау үшін платформа кейбір функцияларды не операцияларды тоқтата тұруы мүмкін. Қызмет техникалық жұмыстар, желі ақаулары немесе форс-мажор салдарынан үзілуі мүмкін; функциялар мен ережелердің өзгерісі қолданбада хабарланады.",
